class K {
  m(): string { return new Error("in method").stack!; }
  static s(): string { return new Error("in static").stack!; }
}
function inner(): string { return new Error("boom").stack!; }
function outer(): string { return inner(); }
function frames(stack: string, count: number): string[] {
  return stack.split("\n").slice(1, 1 + count);
}
function main(): void {
  const lines = frames(outer(), 2);
  console.log(lines.length, lines.every((l: string) => /^    at \S+ \(.*:\d+:\d+\)$/.test(l)));
  console.log(lines[0].includes("at inner "), lines[1].includes("at outer "));
  console.log(frames(new K().m(), 1)[0].includes("at K.m "), frames(K.s(), 1)[0].includes("at K.s "));
}
